    for i in range(NumPeriods):
        model.addConstr(Store[k][i] <= 100, name=f"StorageLimit_{k}_{i}")"}}, {"description": "Inventory balance: storage at end of period equals previous storage plus manufacturing minus sales. No initial stock.", "formulation": "Store_{k,i} = Store_{k,i-1} + Manufacture_{k,i} - Sell_{k,i}, \quad \forall k, i \quad (Store_{k,0} = Manufacture_{k,0} - Sell_{k,0})", "code": {"gurobipy": "for k in range(NumProducts):
    for i in range(NumPeriods):
        if i == 0:
