        else:
            model.addConstr(Store[k][i] == Store[k][i-1] + Manufacture[k][i] - Sell[k][i], name=f"Balance_{k}_{i}")"}}, {"description": "At the end of the last period, we must have KeepQuantity of each product in storage", "formulation": "Store_{k,NumPeriods} = KeepQuantity, \quad \forall k", "code": {"gurobipy": "for k in range(NumProducts):
    model.addConstr(Store[k][NumPeriods-1] == KeepQuantity, name=f"FinalStock_{k}")"}}, {"description": "Products must have non-negative production, sales, and storage quantities", "formulation": "Sell_{k,i} \geq 0, \quad Manufacture_{k,i} \geq 0, \quad Store_{k,i} \geq 0, \quad \forall k, i", "code": {"gurobipy": "for k in range(NumProducts):
