        model.addConstr(Store[k][i] >= 0, name=f"NonNegStore_{k}_{i}")"}}], "objective": {"description": "Maximize the company's profit from selling its products while accounting for storage costs", "formulation": "\max \ \sum_{k=1}^{NumProducts} \sum_{i=1}^{NumPeriods} \left( Profit_{k} \times Sell_{k,i} - StorePrice \times Store_{k,i} \right)", "code": {"gurobipy": "model.setObjective(gurobipy.quicksum(Profit[k] * Sell[k][i] - StorePrice * Store[k][i] for k in range(NumProducts) for i in range(NumPeriods)), GRB.MAXIMIZE)"}}}

