    for t in range(T):
        model.addConstr(Store[p][t] <= 100, name=f"StorageLimit_{p}_{t}")"}}, {"description": "Inventory balance: storage at end of month equals previous storage plus manufacturing minus sales. No initial stock.", "formulation": "Store_{p,t} = Store_{p,t-1} + Manufacture_{p,t} - Sell_{p,t}, \quad \forall p, t \quad (Store_{p,0} = Manufacture_{p,0} - Sell_{p,0})", "code": {"gurobipy": "for p in range(P):
    for t in range(T):
