        else:
            model.addConstr(Store[p][t] == Store[p][t-1] + Manufacture[p][t] - Sell[p][t], name=f"Balance_{p}_{t}")"}}, {"description": "At the end of the last month, we must have KeepQuantity of each product in storage", "formulation": "Store_{p,T} = KeepQuantity, \quad \forall p", "code": {"gurobipy": "for p in range(P):
    model.addConstr(Store[p][T-1] == KeepQuantity, name=f"FinalStock_{p}")"}}, {"description": "Each machine type must have exactly Downtime months of maintenance scheduled over the planning horizon", "formulation": "\sum_{t=1}^{T} Maintain_{m,t} = Downtime_{m} \times NumMachines_{m}, \quad \forall m", "code": {"gurobipy": "for m in range(M):
    model.addConstr(gurobipy.quicksum(Maintain[m][t] for t in range(T)) == Downtime[m] * NumMachines[m], name=f"TotalMaintenance_{m}")"}}, {"description": "Number of machines under maintenance cannot exceed the number of machines of that type", "formulation": "0 \leq Maintain_{m,t} \leq NumMachines_{m}, \quad \forall m, t", "code": {"gurobipy": "for m in range(M):
    for t in range(T):
        model.addConstr(Maintain[m][t] >= 0, name=f"MaintainNonNeg_{m}_{t}")
        model.addConstr(Maintain[m][t] <= NumMachines[m], name=f"MaintainMax_{m}_{t}")"}}, {"description": "All production, sales, and storage variables must be non-negative", "formulation": "Sell_{p,t} \geq 0, \quad Manufacture_{p,t} \geq 0, \quad Store_{p,t} \geq 0, \quad \forall p, t", "code": {"gurobipy": "for p in range(P):
