    model.addConstr(quicksum(ManpowerOne[k] * Produce[k][t] for k in range(NumIndustries)) + quicksum(ManpowerTwo[k] * BuildCapa[k][t] for k in range(NumIndustries)) <= ManpowerLimit, name=f"ManpowerLimit_{t}")"}}, {"description": "Stock levels must be maintained as per Stock non-negativity and limits", "formulation": "StockHold_{k,t} \geq 0, \quad \forall k \in \{1, \ldots, NumIndustries\}, \forall t \in \{1, \ldots, NumYears\}", "code": {"gurobipy": "for k in range(NumIndustries):
