    for t in range(NumYears):
        model.addConstr(Produce[k][t] >= 0, name=f"ProdNonNeg_{k}_{t}")
        model.addConstr(BuildCapa[k][t] >= 0, name=f"BuildNonNeg_{k}_{t}")"}}], "objective": {"description": "Maximize total production in the last two years", "formulation": "\max \sum_{k=1}^{NumIndustries} \sum_{t=NumYears-1}^{NumYears} Produce_{k,t}", "code": {"gurobipy": "model.setObjective(quicksum(Produce[k][t] for k in range(NumIndustries) for t in range(NumYears - 2, NumYears)), GRB.MAXIMIZE)"}}}

