{"parametrized_description": "Determine the optimal path the delivery person should take to ensure the package is delivered in the least amount of time. The path is constrained by the number of east-west streets, N, and the number of north-south streets, W. Each east-west street segment WestTime and each north-south street segment NorthTime takes a certain amount of time to cross.", "keywords": ["optimization", "minimization"], "parameters": {"N": {"description": "Number of east-west streets", "shape": []}, "W": {"description": "Number of north-south streets", "shape": []}, "WestTime": {"description": "Time to cross street segment going west, for given street n and segment w", "shape": ["N", "W"]}, "NorthTime": {"description": "Time to cross street segment going north, for given street n and segment w", "shape": ["W", "N"]}}, "variables": {"WestFlow": {"description": "Flow (fraction) on the westward edge from intersection (n, w) to (n, w+1)", "type": "continuous", "shape": ["N", "W"]}, "NorthFlow": {"description": "Flow (fraction) on the northward edge from intersection (n, w) to (n+1, w)", "type": "continuous", "shape": ["N", "W"]}}, "constraints": [{"description": "The number of east-west street segments used cannot exceed N", "formulation": "\sum_{n=1}^{N} \sum_{w=1}^{W-1} WestFlow_{n,w} + \sum_{n=1}^{N-1} \sum_{w=1}^{W} NorthFlow_{n,w} = (N - 1) + (W - 1)", "code": {"gurobipy": "model.addConstr(
    quicksum(WestFlow[n][w] for n in range(N) for w in range(W - 1))
