    for w in range(W):
        model.addConstr(NorthFlow[n][w] >= 0, name=f"NorthFlowNonNeg_{n}_{w}")"}}], "objective": {"description": "Minimize the total amount of time to deliver the package", "formulation": "\min \ \sum_{n=1}^{N} \sum_{w=1}^{W-1} WestTime_{n,w} \times WestFlow_{n,w} + \sum_{n=1}^{N-1} \sum_{w=1}^{W} NorthTime_{n,w} \times NorthFlow_{n,w}", "code": {"gurobipy": "model.setObjective(
    quicksum(WestTime[n][w] * WestFlow[n][w] for n in range(N) for w in range(W - 1))
    + quicksum(NorthTime[n][w] * NorthFlow[n][w] for n in range(N - 1) for w in range(W)),
