    model.addConstr(quicksum(Route[i][j] for j in range(N) if j != i) == 1, name=f"LeaveCity_{i}")"}}, {"description": "The traveler must return to StartCity after visiting all other towns", "formulation": "\sum_{i=1, i \neq j}^{N} Route_{i,j} = 1 \quad \forall j \in \{1, \ldots, N\}", "code": {"gurobipy": "for j in range(N):
    model.addConstr(quicksum(Route[i][j] for i in range(N) if i != j) == 1, name=f"EnterCity_{j}")"}}, {"description": "The distance between any two towns is non-negative", "formulation": "Order_{i} - Order_{j} + N \times Route_{i,j} \leq N - 1 \quad \forall i, j \in \{1, \ldots, N\}, i \neq StartCity, j \neq StartCity, i \neq j", "code": {"gurobipy": "for i in range(N):
    for j in range(N):
        if i != StartCity and j != StartCity and i != j:
            model.addConstr(Order[i] - Order[j] + N * Route[i][j] <= N - 1, name=f"SubtourElim_{i}_{j}")"}}], "objective": {"description": "Minimize the total travel distance for the route", "formulation": "\min \ \sum_{i=1}^{N} \sum_{j=1, j \neq i}^{N} Distances_{i,j} \times Route_{i,j}", "code": {"gurobipy": "model.setObjective(
    quicksum(Distances[i][j] * Route[i][j] for i in range(N) for j in range(N) if i != j),
    GRB.MINIMIZE)"}}}

{"parametrized_description": "Find the minimum-length Hamiltonian path on a digraph V_T that visits every node exactly once, starting at node s and ending at node t, for city-wide waste collection routing. Binary variables x[i,j] indicate whether arc (i,j) is used. Subtours are eliminated via MTZ position variables u[i]. Additional constraints enforce: direct servicing of long block sides (in set L) via required arcs; traffic turn restrictions (forbidden (i,j,k) triples in F); and forbidden paths of length three and four (in F_4). Arc weights ell[i][j] give the shortest-path length between nodes i and j respecting traffic restrictions.", "keywords": ["vehicle routing", "Hamiltonian path", "TSP", "integer programming", "urban services", "waste collection"], "parameters": {"V_T": {"description": "Set of nodes in the routing digraph (required service nodes plus depot start s and end t)", "shape": ["|V_T|"]}, "ell": {"description": "ell[i][j]: shortest-path length (arc weight) from node i to node j respecting traffic restrictions", "shape": ["|V_T|", "|V_T|"]}, "s": {"description": "Starting depot node", "shape": []}, "t": {"description": "Ending depot node (last node to be visited)", "shape": []}, "L": {"description": "Set of long block sides that must be directly serviced by the truck", "shape": ["|L|"]}, "L_e": {"description": "L_e[e]: list of arcs (i,j) in V_T whose shortest path includes block side e; used to enforce direct service", "shape": ["|L|"]}, "F_4": {"description": "List of forbidden paths of length four, each given as a tuple (u1, u2, u3, u4)", "shape": ["|F_4|"]}, "B_delta": {"description": "B_delta[delta]: set of nodes v such that the last arc of the shortest path from v to u2 is (u1,u2), for delta=(u1,u2,u3,u4)", "shape": ["|F_4|"]}, "hat_B_delta": {"description": "hat_B_delta[delta]: set of nodes v such that the two last arcs of the shortest path from v to u3 are (u1,u2) and (u2,u3)", "shape": ["|F_4|"]}, "E_delta": {"description": "E_delta[delta]: set of nodes v such that the first arc of the shortest path from u3 to v is (u3,u4)", "shape": ["|F_4|"]}, "hat_E_delta": {"description": "hat_E_delta[delta]: set of nodes v such that the two first arcs of the shortest path from u2 to v are (u2,u3) and (u3,u4)", "shape": ["|F_4|"]}, "V_ij": {"description": "V_ij[(i,j)]: set of nodes k such that arc (j,k) is forbidden after arc (i,j) due to traffic restrictions", "shape": ["|V_T|", "|V_T|"]}}, "variables": {"x": {"description": "x[i,j]: binary variable, 1 if arc (i,j) is used in the route, 0 otherwise", "type": "integer", "shape": ["|V_T|", "|V_T|"]}, "u": {"description": "u[i]: continuous MTZ position variable for node i (used for subtour elimination)", "type": "continuous", "shape": ["|V_T|"]}}, "constraints": [{"description": "Each node must be visited exactly once (one incoming arc).", "formulation": "\sum_{i \neq j} x[i,j] = 1 \quad \forall j \in V_T", "code": {"gurobipy": "for j in V_T:
    model.addConstr(gp.quicksum(x[i, j] for i in V_T if i != j) == 1, name=f'visit_{j}')"}}, {"description": "Each node must be left exactly once (one outgoing arc).", "formulation": "\sum_{j \neq i} x[i,j] = 1 \quad \forall i \in V_T", "code": {"gurobipy": "for i in V_T:
    model.addConstr(gp.quicksum(x[i, j] for j in V_T if j != i) == 1, name=f'leave_{i}')"}}, {"description": "MTZ subtour elimination: position of node s is 0; all other nodes have position in [1, |V_T|-1]; MTZ constraint for non-depot nodes.", "formulation": "u[s] = 0; \quad 1 \leq u[i] \leq n-1 \; (i \neq s); \quad u[i] - u[j] + n \cdot x[i,j] \leq n-1 \; (i,j \neq s, i \neq j)", "code": {"gurobipy": "n = len(V_T)
model.addConstr(u[s] == 0)
for i in V_T:
    if i != s:
        model.addConstr(u[i] >= 1)
        model.addConstr(u[i] <= n - 1)
for i in V_T:
    for j in V_T:
        if i != j and i != s and j != s:
            model.addConstr(u[i] - u[j] + n * x[i, j] <= n - 1, name=f'mtz_{i}_{j}')"}}, {"description": "Node t must be the last node visited: arc (t,s) must be used.", "formulation": "x[t, s] = 1", "code": {"gurobipy": "model.addConstr(x[t, s] == 1, name='last_node')"}}, {"description": "Long block sides in L must be directly serviced: at least one arc that covers block side e must be used.", "formulation": "\sum_{(i,j) \in L_e[e]} x[i,j] \geq 1 \quad \forall e \in L", "code": {"gurobipy": "for e in L:
    if L_e.get(str(tuple(e))):
        model.addConstr(gp.quicksum(x[i, j] for (i, j) in L_e[str(tuple(e))]) >= 1, name=f'direct_{e}')"}}, {"description": "Traffic restrictions: if arc (i,j) is used, forbidden successor arcs (j,k) for k in V_ij[(i,j)] cannot be used.", "formulation": "\sum_{k \in V_{(i,j)}} x[j,k] \leq 1 - x[i,j] \quad \forall i \neq j", "code": {"gurobipy": "for i in V_T:
    for j in V_T:
        if i != j:
            model.addConstr(gp.quicksum(x[j, k] for k in V_ij[str((i, j))]) <= 1 - x[i, j], name=f'traffic_{i}_{j}')"}}, {"description": "Forbidden four-node paths: three subtraction constraints prevent each forbidden path delta=(u1,u2,u3,u4) from being traversed.", "formulation": "\sum_{v \in B_\delta} x[v,u_2] + x[u_2,u_3] + \sum_{v \in E_\delta} x[u_3,v] \leq 2; \quad \sum_{v \in \hat{B}_\delta} x[v,u_3] + \sum_{v \in E_\delta} x[u_3,v] \leq 1; \quad \sum_{v \in B_\delta} x[v,u_2] + \sum_{v \in \hat{E}_\delta} x[u_2,v] \leq 1 \quad \forall \delta \in F_4", "code": {"gurobipy": "for delta in F_4:
    u1, u2, u3, u4 = delta
    model.addConstr(gp.quicksum(x[v, u2] for v in B_delta[str(tuple(delta))]) + x[u2, u3] + gp.quicksum(x[u3, v] for v in E_delta[str(tuple(delta))]) <= 2)
    model.addConstr(gp.quicksum(x[v, u3] for v in hat_B_delta[str(tuple(delta))]) + gp.quicksum(x[u3, v] for v in E_delta[str(tuple(delta))]) <= 1)
    model.addConstr(gp.quicksum(x[v, u2] for v in B_delta[str(tuple(delta))]) + gp.quicksum(x[u2, v] for v in hat_E_delta[str(tuple(delta))]) <= 1)"}}], "objective": {"description": "Minimize the total length of the waste collection route.", "formulation": "\min \sum_{i \in V_T} \sum_{j \in V_T, j \neq i} \ell[i][j] \cdot x[i,j]", "code": {"gurobipy": "model.setObjective(gp.quicksum(ell[i][j] * x[i, j] for i in V_T for j in V_T if i != j), GRB.MINIMIZE)"}}}

{"parametrized_description": "Maximize multiorder hits in an online grocery order consolidation system over a rolling planning horizon. Starting from period t, for each period tau, pool cohort s, and probability group k, decide how many orders O[tau,s,k] to release from the pool. The pool state S[tau,s,k] evolves across periods accounting for arriving orders (I[tau]), multiorder hits (epsilon[tau][s][k]), and releases (O[tau,s,k]). Constraints enforce: maximum outbound flow F_bar[tau] per period (with penalty c_F[tau] for violations); maximum pool stay L; pool size cap C[tau]; end-of-horizon pool emptying; and the state transition equations linking S, S_prime (post-clearance state), and O.", "keywords": ["order consolidation", "linear programming", "e-commerce", "rolling horizon", "inventory management"], "parameters": {"T": {"description": "Total number of periods in the planning horizon", "shape": []}, "t": {"description": "Current period (starting period for the rolling horizon)", "shape": []}, "L": {"description": "Maximum number of periods an order may stay in the pool", "shape": []}, "K": {"description": "Number of probability groups for multiorder classification", "shape": []}, "I": {"description": "I[tau]: number of new orders arriving at the system in period tau", "shape": ["T"]}, "I_prime": {"description": "I_prime[tau][k]: number of multiorders remaining in group k after clearance in period tau", "shape": ["T", "K"]}, "epsilon": {"description": "epsilon[tau][s][k]: number of orders in pool cohort (tau,s,k) that are hit by multiorders (given/fixed input)", "shape": ["T", "L", "K"]}, "C": {"description": "C[tau]: maximum number of orders that can be held in the pool at period tau", "shape": ["T"]}, "F_bar": {"description": "F_bar[tau]: maximum number of fulfillment orders that can be released from the pool in period tau", "shape": ["T"]}, "p": {"description": "p[k]: middle value of the multiorder probability interval for group k", "shape": ["K"]}, "c_F": {"description": "c_F[tau]: per-unit penalty for violating the maximum flow constraint in period tau", "shape": ["T"]}}, "variables": {"S": {"description": "S[tau,s,k]: number of orders in group k that arrived at period s and are in the pool at the beginning of period tau (before clearance)", "type": "continuous", "shape": ["T+2", "T+2", "K"]}, "S_prime": {"description": "S_prime[tau,s,k]: number of orders in group k that arrived at period s and remain in the pool after multiorder clearance at period tau", "type": "continuous", "shape": ["T+1", "T+1", "K"]}, "O": {"description": "O[tau,s,k]: number of orders from group k that arrived at period s and are released from the pool at period tau", "type": "continuous", "shape": ["T+1", "T+1", "K"]}}, "constraints": [{"description": "Pool state after clearance equals pool state before clearance minus multiorder hits.", "formulation": "S'[\tau,s,k] = S[\tau,s,k] - \epsilon[\tau][s][k] \quad \forall \tau, s \in [\tau-L+1,\tau], k", "code": {"gurobipy": "for tau in range(t, T + 1):
    for k in range(K):
        for s in range(tau - L + 1, tau + 1):
            model.addConstr(S_prime[tau, s, k] == S[tau, s, k] - epsilon[str(tau)][str(s)][k],
                            name=f'Clearance_{tau}_{s}_{k}')
        model.addConstr(S_prime[tau, tau, k] == I_prime[str(tau)][k], name=f'Arrival_{tau}_{k}')"}}, {"description": "Pool state transition: the pool state at the start of next period equals post-clearance state minus releases.", "formulation": "S[\tau+1,s,k] = S'[\tau,s,k] - O[\tau,s,k] \quad \forall \tau, s \in [\tau-L+1,\tau], k", "code": {"gurobipy": "for tau in range(t, T + 1):
    for k in range(K):
        for s in range(tau - L + 1, tau + 1):
            model.addConstr(S[tau + 1, s, k] == S_prime[tau, s, k] - O[tau, s, k],
                            name=f'Transition_{tau}_{s}_{k}')"}}, {"description": "Orders that have reached maximum stay L must be released.", "formulation": "O[\tau, \tau-L, k] = S'[\tau, \tau-L, k] \quad \forall \tau, k", "code": {"gurobipy": "for tau in range(t, T + 1):
    for k in range(K):
        model.addConstr(O[tau, tau - L, k] == S_prime[tau, tau - L, k],
                        name=f'MaxStay_{tau}_{k}')"}}, {"description": "Pool size cap: total orders in the pool at each period must not exceed C[tau].", "formulation": "\sum_{s=\tau-L+1}^{\tau} \sum_{k} S[\tau+1,s,k] \leq C[\tau] \quad \forall \tau", "code": {"gurobipy": "for tau in range(t, T + 1):
    model.addConstr(
        gp.quicksum(S[tau + 1, s, k] for s in range(tau - L + 1, tau + 1) for k in range(K))
        <= C[str(tau)], name=f'PoolCap_{tau}')"}}, {"description": "End-of-horizon constraint: the pool must be empty at the end of the horizon.", "formulation": "S[T+1, T+1, k] = 0 \quad \forall k", "code": {"gurobipy": "for k in range(K):
    model.addConstr(S[T + 1, T + 1, k] == 0, name=f'EndHorizon_{k}')"}}, {"description": "Non-negativity of pool state and release variables.", "formulation": "S[\tau,s,k] \geq 0, \quad O[\tau,s,k] \geq 0 \quad \forall \tau, s, k", "code": {"gurobipy": "for tau1 in range(T + 1):
    for tau2 in range(T + 1):
        for k in range(K):
            model.addConstr(S[tau1, tau2, k] >= 0)
            model.addConstr(O[tau1, tau2, k] >= 0)"}}], "objective": {"description": "Maximize total multiorder hits (weighted by probability p[k]) minus penalties for exceeding maximum outbound flow.", "formulation": "\max \sum_{\tau=t}^{T} \sum_{s=\tau-L+1}^{\tau} \sum_{k} p[k] \cdot S[\tau+1,s,k] - \sum_{\tau=t}^{T} c_F[\tau] \cdot \left( \sum_{s,k} O[\tau,s,k] - \bar{F}[\tau] \right)", "code": {"gurobipy": "model.setObjective(
    gp.quicksum(
        p[k] * S[tau + 1, s, k]
        for tau in range(t, T + 1)
        for s in range(tau - L + 1, tau + 1)
        for k in range(K)
    )
    - gp.quicksum(
        c_F[str(tau)] * (
            gp.quicksum(O[tau, s, k] for s in range(tau - L, tau + 1) for k in range(K))
            - F_bar[str(tau)]
        )
        for tau in range(t, T + 1)
    ),
    GRB.MAXIMIZE)"}}}
